#include "mu/motion_animation.hpp"
#include <cassert>
#include <iostream>
using namespace mu::core::bmd;
Model fixture(){Model model;model.bones.resize(1);for(unsigned action:{1u,4u,15u,17u,25u,38u,146u,147u,231u,232u}){auto a=model.bones,b=model.bones;a[0].position.x=float(action);b[0].position.x=float(action)+10;model.clips[action]={a,b};model.lockedPositions[action]=false;}return model;}
int main(){auto model=fixture();MotionAnimation motion(model,{1,15,25});auto start=motion.sample(0,0);assert(start[0].position.x==1);
 auto transition=motion.sample(0,1);assert(transition[0].position.x==1);auto middle=motion.sample(.06,1);auto target=sample_pose(model,15,.06,8.25);assert(std::abs(middle[0].position.x-(1+target[0].position.x)*.5)<.0001f);
 auto end=motion.sample(.12,1);target=sample_pose(model,15,.12,8.25);assert(std::abs(end[0].position.x-target[0].position.x)<.0001f);
 motion.sample(.12,2);auto running=motion.sample(.24,2);target=sample_pose(model,25,.24,8.5);assert(std::abs(running[0].position.x-target[0].position.x)<.0001f);
 motion.sample(.24,0);auto idle=motion.sample(.36,0);target=sample_pose(model,1,.12,2/1.2);assert(std::abs(idle[0].position.x-target[0].position.x)<.0001f);
 bool failed=false;try{motion.sample(.1,0);}catch(const std::exception&){failed=true;}assert(failed);
 MotionAnimation sixty(model,{1,15,25}),oneTwenty(model,{1,15,25});sixty.sample(0,0);oneTwenty.sample(0,0);std::vector<Bone> a,b;for(unsigned i=1;i<=120;i++)a=sixty.sample(i/60.,1);for(unsigned i=1;i<=240;i++)b=oneTwenty.sample(i/120.,1);assert(std::abs(a[0].position.x-b[0].position.x)<.0001f);
 auto normalized=fixture();normalized.clips[15][0][0].position={500,600,700};normalize_motion_roots(normalized,{1,15,25},1);assert(normalized.clips[15][0][0].position.x==1&&normalized.clips[15][0][0].position.y==0&&normalized.clips[15][0][0].position.z==700);
 MotionAnimation combat(model,{1,15,25,38});combat.sample(0,0);combat.sample(0,3);auto strike=combat.sample(.12,3);auto attackTarget=sample_pose(model,38,.12,2/.6);assert(std::abs(strike[0].position.x-attackTarget[0].position.x)<.0001f);combat.sample(.12,1);auto after=combat.sample(.24,1);attackTarget=sample_pose(model,15,.12,8.25);assert(std::abs(after[0].position.x-attackTarget[0].position.x)<.0001f);
 MotionAnimation spell(model,{1,15,25,38,146,147});spell.sample(0,0);spell.sample(0,5);auto cast=spell.sample(.12,5);auto castTarget=sample_pose(model,147,.12,2/.6);assert(std::abs(cast[0].position.x-castTarget[0].position.x)<.0001f);spell.sample(.12,4);cast=spell.sample(.24,4);castTarget=sample_pose(model,146,.12,2/.6);assert(std::abs(cast[0].position.x-castTarget[0].position.x)<.0001f);
 MotionAnimation world(model,{1,15,25,38,4,17},true);world.sample(0,4);auto worldIdle=world.sample(.12,4);auto expectedIdle=sample_pose(model,4,.12,2/1.2);assert(std::abs(worldIdle[0].position.x-expectedIdle[0].position.x)<.0001f);world.sample(.12,5);auto worldWalk=world.sample(.24,5);auto expectedWalk=sample_pose(model,17,.12,8.25);assert(std::abs(worldWalk[0].position.x-expectedWalk[0].position.x)<.0001f);world.sample(.24,2);auto worldRun=world.sample(.36,2);auto expectedRun=sample_pose(model,25,.24,8.5);assert(std::abs(worldRun[0].position.x-expectedRun[0].position.x)<.0001f);
 assert(std::abs(sixty.frame()-oneTwenty.frame())<.0001);assert(world.currentMode()==2);assert(world.frame()>=0&&world.frame()<2);MotionAnimation castWorld(model,{1,15,25,38,4,17,146,147},true);castWorld.sample(0,6);auto hand=castWorld.sample(.12,6);auto handExpected=sample_pose(model,146,.12,2/.6);assert(std::abs(hand[0].position.x-handExpected[0].position.x)<.0001f);assert(castWorld.currentMode()==6);
 std::vector<unsigned> deathModes(16,1);deathModes.push_back(231);deathModes.push_back(232);MotionAnimation death(model,deathModes,true);death.sample(0,0);death.sample(0,16);auto falling=death.sample(.04,16);assert(death.frame()>0&&death.frame()<1);auto corpse=death.sample(1,16);assert(corpse[0].position.x==241);assert(death.frame()==1);auto frozen=death.sample(4,16);assert(frozen[0].position.x==corpse[0].position.x);death.sample(4,0);auto alive=death.sample(4.2,0);assert(alive[0].position.x!=corpse[0].position.x);
 std::cout<<"motion animation contract passed\n";
}
